const opType = msg.operationType || 'read';

if (opType === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

flow.set("bmaint_rpc_response_topic", msg.rpcResponseTopic);
flow.set("bmaint_write_result", msg.writeResult || null);

return msg;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 211,
    quantity: 4
};
return msg;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data) || data.length < 4) {
    node.status({ fill: "red", shape: "dot", text: "Read failed" });
    return null;
}

const reg211 = data[0];
const reg212 = data[1];
const reg213 = data[2];
const reg214 = data[3];

// Parse battery control mode
const modeMap = {
    0: "voltage",
    1: "capacity",
    2: "no_battery"
};
const batteryControlMode = modeMap[reg211] || "no_battery";

// Parse wake up (inverted: 0=enabled, 1=disabled)
const channel1Enabled = reg212 === 0;

// Resistance
const batteryResistanceMilliOhm = reg213;

// Charge efficiency (0.1% scale)
const chargeEfficiencyPercent = Math.round(reg214 * 0.1 * 10) / 10;

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";

const state = {
    kind: "BatteryMaintenanceConfigState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    gatewayId: gatewayId,
    batteryControlMode: batteryControlMode,
    wakeUp: {
        channel1Enabled: channel1Enabled,
        channel2Enabled: null
    },
    batteryResistanceMilliOhm: batteryResistanceMilliOhm,
    chargeEfficiencyPercent: chargeEfficiencyPercent
};

// Check if this is after a write
const writeResult = flow.get("bmaint_write_result");
flow.set("bmaint_write_result", null);

if (writeResult) {
    msg.payload = {
        success: true,
        message: `Updated ${writeResult.count} register(s)`,
        writes: writeResult.writes,
        state: state
    };
} else {
    msg.payload = state;
}

node.status({ fill: "green", shape: "dot", text: batteryControlMode || "no_battery" });

return msg;

const params = msg.rpcParams || {};
const writes = [];

// 211: batteryControlMode
if (params.batteryControlMode !== undefined) {
    let val = 1; // default capacity
    if (params.batteryControlMode === "voltage") val = 0;
    else if (params.batteryControlMode === "capacity") val = 1;
    else if (params.batteryControlMode === "no_battery" || params.batteryControlMode === null) val = 2;
    writes.push({ register: 211, value: val, name: "Battery Control Mode" });
}

// 212: wakeUp.channel1Enabled (inverted: 0=enabled, 1=disabled)
if (params.wakeUp && params.wakeUp.channel1Enabled !== undefined) {
    const val = params.wakeUp.channel1Enabled ? 0 : 1;
    writes.push({ register: 212, value: val, name: "Wake Up Channel 1" });
}

// 213: batteryResistanceMilliOhm
if (params.batteryResistanceMilliOhm !== undefined) {
    const val = Math.max(0, Math.min(6000, params.batteryResistanceMilliOhm));
    writes.push({ register: 213, value: val, name: "Battery Resistance" });
}

// 214: chargeEfficiencyPercent (0.1% scale)
if (params.chargeEfficiencyPercent !== undefined) {
    const val = Math.round(params.chargeEfficiencyPercent * 10);
    const clampedVal = Math.max(0, Math.min(1000, val));
    writes.push({ register: 214, value: clampedVal, name: "Charge Efficiency" });
}

if (writes.length === 0) {
    node.warn("No valid parameters to write");
    return null;
}

global.set("bmaint_write_queue", writes);
global.set("bmaint_write_index", 0);

node.status({ fill: "blue", shape: "dot", text: writes.length + " writes queued" });

return msg;

const writes = global.get("bmaint_write_queue") || [];
const index = global.get("bmaint_write_index") || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

msg.payload = {
    fc: 16,
    unitid: 1,
    address: current.register,
    quantity: 1,
    value: [current.value]
};
msg.currentWrite = current;

node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });

return msg;

const writes = global.get("bmaint_write_queue") || [];
let index = global.get("bmaint_write_index") || 0;

const current = msg.currentWrite;
const results = global.get("bmaint_write_results") || [];

if (current) {
    results.push({
        register: current.register,
        name: current.name,
        value: current.value,
        success: true
    });
    global.set("bmaint_write_results", results);
}

index++;
global.set("bmaint_write_index", index);

node.status({ fill: "green", shape: "dot", text: `${current.name} OK` });

if (index < writes.length) {
    return [msg, null];
}

// All writes done - trigger read
msg.writeResult = {
    count: results.length,
    writes: results
};

global.set("bmaint_write_queue", null);
global.set("bmaint_write_index", null);
global.set("bmaint_write_results", null);

return [null, msg];

const rpcTopic = flow.get("bmaint_rpc_response_topic");
flow.set("bmaint_rpc_response_topic", null);

if (!rpcTopic) {
    return null;
}

msg.topic = rpcTopic;
return msg;
